package org.asundr;

public class CommonUtils
{
    public static String sanitizeTags(final String s)
    {
        return s.replaceAll("<[^>]*>", "").trim();
    }

    public static String removeMemberSuffix(final String s) { return s.replace(" (Members)", ""); }

    public  static String sanitizeTradeMenuTarget(final String s)
    {
        return removeMemberSuffix(sanitizeTags(s));
    }
}

